    const debounced = debounce(() => {
        callCount++;
        console.log('Function called');
    }, 100);

    // Call multiple times quickly
    debounced();
    debounced();
    debounced();

    // Wait for the debounce delay
    setTimeout(() => {
        if (callCount === 1) {
            console.log('all tests passed');
        } else {
            console.error('Expected 1 call, got', callCount);
            process.exit(1);
        }
    }, 150);
}

